parameters.jsCode:
const item = $input.first();
const json = item?.json && typeof item.json === 'object' ? { ...item.json } : {};
const body = json.body && typeof json.body === 'object' && !Array.isArray(json.body)
  ? { ...json.body }
  : {};
const binary = item?.binary && typeof item.binary === 'object' ? { ...item.binary } : {};

const imageRefs = [];
const seenImageRefs = new Set();

const previewRef = (value) => {
  const text = String(value || '').trim();
  if (/^data:image\/[a-z0-9.+-]+;base64,/i.test(text)) {
    return text.slice(0, 96) + '... [base64 omitted]';
  }
  return text.length > 160 ? text.slice(0, 160) + '... [truncated]' : text;
};

const addImageRef = (value) => {
  if (typeof value !== 'string') return;
  const trimmed = value.trim();
  if (!trimmed) return;
  if (seenImageRefs.has(trimmed)) return;

  if (/^data:image\/[a-z0-9.+-]+;base64,/i.test(trimmed)) {
    seenImageRefs.add(trimmed);
    imageRefs.push(trimmed);
    return;
  }

  if (trimmed.startsWith('http://') || trimmed.startsWith('https://')) {
    throw new Error('Batshit n8n image inputs must be data:image/... base64 URIs for direct AI Agent binary passthrough. Received an http(s) image URL: ' + previewRef(trimmed));
  }

  throw new Error('Batshit image input must be a data:image/... base64 URI. Received: ' + previewRef(trimmed));
};

const extensionForMime = (mimeType) => {
  const normalized = String(mimeType || '').toLowerCase();
  if (normalized === 'image/jpeg') return 'jpg';
  if (normalized === 'image/svg+xml') return 'svg';
  const match = normalized.match(/^image\/([a-z0-9.+-]+)$/);
  return match ? match[1].replace(/[^a-z0-9]+/g, '') || 'img' : 'img';
};

const addDataUriBinary = (dataUri, index) => {
  const match = dataUri.match(/^data:(image\/[a-z0-9.+-]+);base64,([a-z0-9+/=\r\n]+)$/i);
  if (!match) {
    throw new Error('Batshit image data URI #' + (index + 1) + ' is not valid base64 image data.');
  }

  const mimeType = match[1].toLowerCase();
  const base64 = match[2].replace(/\s+/g, '');
  if (!base64) {
    throw new Error('Batshit image data URI #' + (index + 1) + ' is empty.');
  }

  const key = 'image_' + (Object.keys(binary).filter((name) => name.startsWith('image_')).length + 1);
  const fileExtension = extensionForMime(mimeType);
  binary[key] = {
    data: base64,
    mimeType,
    fileName: 'batshit-image-' + (index + 1) + '.' + fileExtension,
    fileExtension,
  };
};

const collectImageRefs = (value, options = {}) => {
  const allowDirectString = options.allowDirectString === true;
  if (!value) return;
  if (typeof value === 'string') {
    if (allowDirectString) addImageRef(value);
    return;
  }
  if (Array.isArray(value)) {
    for (const entry of value) collectImageRefs(entry, options);
    return;
  }
  if (typeof value !== 'object') return;

  addImageRef(value.url);
  addImageRef(value.imageUrl);
  if (value.image_url && typeof value.image_url === 'object') addImageRef(value.image_url.url);
  if (value.imageUrl && typeof value.imageUrl === 'object') addImageRef(value.imageUrl.url);
};

const collectText = (value, parts = []) => {
  if (!value) return parts;
  if (typeof value === 'string') {
    if (value.trim()) parts.push(value);
    return parts;
  }
  if (Array.isArray(value)) {
    for (const entry of value) collectText(entry, parts);
    return parts;
  }
  if (typeof value !== 'object') return parts;
  if (value.type === 'text' && typeof value.text === 'string' && value.text.trim()) {
    parts.push(value.text);
  }
  return parts;
};

collectImageRefs(body.batshit_image_inputs, { allowDirectString: true });
collectImageRefs(body.batshitImageInputs, { allowDirectString: true });
collectImageRefs(body.batshit_image_urls, { allowDirectString: true });
collectImageRefs(body.batshitImageUrls, { allowDirectString: true });
collectImageRefs(body.chatInput);

for (const [index, dataUri] of imageRefs.entries()) {
  addDataUriBinary(dataUri, index);
}

const textParts = collectText(body.chatInput);
const fallbackText = typeof body.user_message === 'string' ? body.user_message : '';
body.chatInputText = typeof body.chatInputText === 'string' && body.chatInputText.trim()
  ? body.chatInputText
  : (textParts.join('\n\n').trim() || (typeof body.chatInput === 'string' ? body.chatInput : fallbackText));
body.batshit_image_inputs = imageRefs;
body.batshitImageInputs = imageRefs;
body.batshit_image_urls = imageRefs;
body.batshitImageUrls = imageRefs;
body.batshit_image_count = imageRefs.length;
body.batshitImageCount = imageRefs.length;
json.body = body;

const output = { json };
if (Object.keys(binary).length > 0) output.binary = binary;
return [output];

